#!/usr/bin/env python3
import urllib.request, urllib.parse, http.cookiejar, sys, time

IDP = "http://oj-10-30-15-1-58595.adworld.xctf.org.cn"
SP  = "http://oj-10-30-15-1-49263.adworld.xctf.org.cn"
UA = "Mozilla/5.0"

def make_opener():
    cj = http.cookiejar.CookieJar()
    return urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj)), cj

def req(op, url, data=None, method=None):
    if data is not None and not isinstance(data, bytes):
        data = urllib.parse.urlencode(data).encode()
    r = urllib.request.Request(url, data=data, method=method, headers={"User-Agent": UA})
    try:
        resp = op.open(r, timeout=25)
        return resp.status, resp.geturl(), resp.read()
    except urllib.error.HTTPError as e:
        return e.code, url, e.read()

def check_alive():
    op,_ = make_opener()
    for base in (IDP, SP):
        print(base, req(op, base)[0])

def main():
    op, cj = make_opener()
